// 崩溃复现脚本：用法 node repro.js <port> [--split-delay-ms=N]
// 模拟三类偶发请求：A 畸形/截断 JSON、B 多字节字符跨 chunk 切断、C 客户端中途断开
const net = require('net');

const port = Number(process.argv[2] || 3000);
const splitDelay = Number((process.argv.find(a => a.startsWith('--split-delay-ms=')) || '').split('=')[1] || 30);

function rawRequest(payloadBufs, opts = {}) {
  return new Promise((resolve) => {
    const bodyLen = payloadBufs.reduce((n, b) => n + b.length, 0);
    const head =
      `POST /entries HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\n` +
      `Content-Length: ${bodyLen}\r\nConnection: close\r\n\r\n`;
    const sock = net.connect(port, '127.0.0.1', () => {
      sock.write(head);
      let i = 0;
      const writeNext = () => {
        if (i >= payloadBufs.length) { if (opts.destroyAtEnd) sock.destroy(); return; }
        sock.write(payloadBufs[i++]);
        setTimeout(writeNext, splitDelay);
      };
      writeNext();
    });
    let done = false;
    const finish = (code) => { if (!done) { done = true; resolve(code); } };
    sock.on('data', (d) => { if (d.includes('200')) finish('200'); else if (d.includes('400')) finish('400'); });
    sock.on('close', () => finish('closed'));
    sock.on('error', (e) => finish('err:' + e.code));
    setTimeout(() => { sock.destroy(); finish('timeout'); }, 3000);
  });
}

async function waitServer() {
  for (let i = 0; i < 50; i++) {
    const ok = await new Promise((r) => {
      const s = net.connect(port, '127.0.0.1', () => { s.destroy(); r(true); });
      s.on('error', () => r(false));
    });
    if (ok) return;
    await new Promise((r) => setTimeout(r, 100));
  }
  throw new Error('server not up');
}

(async () => {
  await waitServer();

  // A. 畸形 JSON（客户端 bug / 手工 curl 敲错）
  const a = await rawRequest([Buffer.from('{"amount":1,')]);
  console.log('A 畸形JSON      ->', a);

  if (a !== 'closed' && a !== 'timeout') {
    // B. 合法 JSON，但「中」字(3字节)被从中间切开分两个包发 —— 服务端 body += c 逐段解码会损坏
    const payload = Buffer.from(JSON.stringify({ amount: 9, note: '中' }), 'utf8');
    const cut = payload.indexOf(Buffer.from('中', 'utf8')) + 1; // 切在第2字节处
    const b = await rawRequest([payload.subarray(0, cut), payload.subarray(cut)]);
    console.log('B 多字节切断   ->', b);

    // C. 发一半直接断开（弱网/用户杀进程）
    const c = await rawRequest([Buffer.from('{"amount":2,"note":"xx')], { destroyAtEnd: true });
    console.log('C 中途断开     ->', c);

    // 服务器还活着吗？
    const alive = await new Promise((r) => {
      const s = net.connect(port, '127.0.0.1', () => { s.destroy(); r(true); });
      s.on('error', () => r(false));
    });
    console.log('服务器仍存活   ->', alive);
  }
})();

