// 随机压力测试：node stress.js <port> [总请求数]
// 混合合法请求、畸形 JSON、截断体、随机偏移分包（含多字节字符内部）、中途断开、并发
const net = require('net');
const port = Number(process.argv[2] || 3000);
const total = Number(process.argv[3] || 400);

let stats = { ok200: 0, bad400: 0, aborted: 0, neterr: 0 };
const notesSeen = [];

function oneRequest(kind) {
  return new Promise((resolve) => {
    const valid = Buffer.from(JSON.stringify({ amount: Math.round(Math.random() * 100), note: '中文备注🍺tag' + Math.random().toString(36).slice(2, 6) }), 'utf8');
    let bufs, destroy = false, expectValid = true;
    if (kind === 0) { bufs = [valid]; }
    else if (kind === 1) { bufs = [Buffer.from('{"amount":1,')]; expectValid = false; }           // 畸形
    else if (kind === 2) { bufs = [valid.subarray(0, valid.length - 5)]; expectValid = false; }    // 截断
    else if (kind === 3) { const cut = 1 + Math.floor(Math.random() * (valid.length - 2)); bufs = [valid.subarray(0, cut), valid.subarray(cut)]; } // 随机偏移切两包
    else if (kind === 4) { bufs = [Buffer.from('not json at all')]; expectValid = false; }         // 纯垃圾
    else { bufs = [valid.subarray(0, 10)]; destroy = true; expectValid = false; }                  // 发一半断开

    const bodyLen = bufs.reduce((n, b) => n + b.length, 0);
    const head = `POST /entries HTTP/1.1\r\nHost: localhost\r\nContent-Length: ${bodyLen}\r\nConnection: close\r\n\r\n`;
    const sock = net.connect(port, '127.0.0.1', () => {
      sock.write(head);
      let i = 0;
      const next = () => {
        if (i >= bufs.length) { if (destroy) sock.destroy(); return; }
        sock.write(bufs[i++]);
        setTimeout(next, 2 + Math.floor(Math.random() * 20));
      };
      next();
    });
    let body = '';
    let settled = false;
    const done = (r) => { if (!settled) { settled = true; resolve(r); } };
    sock.on('data', (d) => {
      body += d.toString();
      const m = body.match(/^HTTP\/1\.1 (\d{3})/);
      if (m) {
        const code = m[1];
        if (code === '200') { stats.ok200++; if (expectValid) notesSeen.push(body); done('200'); }
        else { stats.bad400++; done(code); }
        if (destroy) sock.destroy();
      }
    });
    sock.on('close', () => { if (!settled) { stats.aborted++; done('closed-no-resp'); } });
    sock.on('error', (e) => { if (!settled) { stats.neterr++; done('neterr:' + e.code); } });
    setTimeout(() => { sock.destroy(); done('timeout'); }, 4000);
  });
}

(async () => {
  // 先等端口就绪
  for (let i = 0; i < 50; i++) {
    const ok = await new Promise((r) => { const s = net.connect(port, '127.0.0.1', () => { s.destroy(); r(true); }); s.on('error', () => r(false)); });
    if (ok) break;
    await new Promise((r) => setTimeout(r, 100));
  }

  let inFlight = 0, sent = 0;
  await new Promise((allDone) => {
    const maybeFinish = () => { if (sent >= total && inFlight === 0) allDone(); };
    const launch = () => {
      while (inFlight < 20 && sent < total) {
        const kind = Math.floor(Math.random() * 6);
        inFlight++; sent++;
        oneRequest(kind).then(() => { inFlight--; maybeFinish(); launch(); });
      }
      maybeFinish();
    };
    launch();
  });

  // 服务器是否仍存活 + 数据完整性
  const alive = await new Promise((r) => {
    const s = net.connect(port, '127.0.0.1', () => { s.destroy(); r(true); }); s.on('error', () => r(false));
  });
  console.log('存活:', alive, '| 统计:', JSON.stringify(stats));

  // 完整性：GET 出来的所有 note 必须是未被损坏的原始字符串（不含 U+FFFD）
  const get = await new Promise((r) => {
    http = require('http');
    http.get(`http://127.0.0.1:${port}/entries`, (res) => { let b = ''; res.on('data', (c) => b += c); res.on('end', () => r(b)); }).on('error', () => r(null));
  });
  if (get === null) { console.log('完整性: GET 失败'); process.exit(1); }
  const entries = JSON.parse(get);
  const corrupted = entries.filter((e) => e.note && e.note.includes('�'));
  console.log(`完整性: 共 ${entries.length} 条, 含损坏 note 的条数 = ${corrupted.length}`);
  process.exit(alive && corrupted.length === 0 ? 0 : 1);
})();

